#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Turns monitoring on in production (spec #214, ADR 0027): the owner signs up to Bugsink,
# UptimeRobot and Healthchecks.io, sets up Umami on the VPS, deploys, and checks that every
# tool reports. Run from anywhere in the repository, once the VPS is online
# (scripts/vps/setup-vps.sh):
#
#   scripts/vps/setup-monitoring.sh
#
# The tools' values land only in the host's `.env`, over SSH, which the deploy never touches
# (ADR 0012). The VPS's address and paths come from `.env.vps`, which setup-vps.sh keeps. A
# second run offers to keep what the host already has, so it also redoes a single tool.

WRITTEN_HOST=() # KEYs written to the host's .env this run
TURNED_OFF=()   # tools the owner stopped at, which stay off
CHECKED=()      # the checks the owner saw pass, for the comment on #214
MAILBOX=""      # the project's mailbox, read from SECURITY.md
UMAMI_TUNNEL="" # pid of the open SSH tunnel to Umami's dashboard
RELEASE=""      # the release the site serves once deployed

# on_host runs the script on its stdin on the host, in DEPLOY_PATH, as the deploy user.
on_host() {
  # BatchMode: fail instead of asking for a password; the deploy user takes keys only.
  # shellcheck disable=SC2029 # DEPLOY_PATH expands here on purpose, quoted by printf %q.
  ssh -o BatchMode=yes "$DEPLOYER" "cd $(printf %q "$DEPLOY_PATH") && bash -s"
}

# host_env KEY prints KEY's value in the host's .env, empty when it has none.
host_env() {
  # `cut -d= -f2-`: everything after the first `=`.
  on_host <<<"grep -E '^$1=' .env | tail -n 1 | cut -d= -f2-"
}

# write_host_env KEY VALUE upserts KEY=VALUE in the host's .env and sets $KEY. The value travels
# on ssh's stdin, so no process list on either machine shows it; callers check it against a
# pattern first, so it needs no quoting. `cat >` keeps the file's mode.
write_host_env() {
  local key="$1" value="$2"
  # Its callers run it inside `if`, where `set -e` does not stop the wizard: hence the `||`.
  # shellcheck disable=SC2029 # DEPLOY_PATH and KEY expand here on purpose.
  printf '%s\n' "$value" | ssh -o BatchMode=yes "$DEPLOYER" "cd $(printf %q "$DEPLOY_PATH") &&
    IFS= read -r value && umask 077 &&
    { grep -v '^$key=' .env || true; printf '%s=%s\n' '$key' \"\$value\"; } > .env.new &&
    cat .env.new > .env && rm .env.new" || { warn "Could not write $key to the host's .env."; exit 1; }
  printf -v "$key" '%s' "$value"
  WRITTEN_HOST+=("$key")
  printf "  %s✓ wrote%s %s → the host's .env\n" "$GREEN" "$RESET" "$key"
}

# ask_host_env KEY "Prompt" PATTERN [hidden] sets $KEY: the host's current value if the owner
# keeps it, else an answer matching PATTERN, written to the host's .env. Returns 1 when the
# owner kept the current value, so the caller knows nothing changed.
ask_host_env() {
  local key="$1" prompt="$2" pattern="$3" hidden="${4:-}" current input
  current=$(host_env "$key")
  if [[ -n "$current" ]]; then
    note "The host's .env already sets $key."
    if confirm "Keep it?"; then printf -v "$key" '%s' "$current"; return 1; fi
  fi
  while :; do
    if [[ -n "$hidden" ]]; then
      printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
      read -rs input
      printf '\n'
    else
      read -e -r -p "  $prompt " input
    fi
    [[ "$input" =~ $pattern ]] && break
    warn "That does not look like $key: copy it again."
  done
  write_host_env "$key" "$input"
}

# free_alerts_or_stop TOOL PRICING_URL asks the owner to check, at sign-up, that TOOL's free plan
# emails alerts: the pages read on 2026-11-25 did not confirm it (research/monitoraggio-analytics.md).
# Fails when it does not, and the tool stays off: the owner decides what to do before turning it on.
free_alerts_or_stop() {
  local tool="$1" url="$2"
  open_url "$url"
  step "Check that $tool's free plan includes email alerts."
  if confirm "Does it?"; then return 0; fi
  warn "$tool stays off: choose another plan or another tool before turning it on."
  TURNED_OFF+=("$tool")
  SKIPPED+=("$tool: its free plan has no email alerts, so it stays off")
  pause "Press Enter to go on to the next tool."
  return 1
}

# is_off TOOL succeeds when the owner stopped at TOOL this run.
is_off() {
  local tool
  for tool in "${TURNED_OFF[@]}"; do [[ "$tool" == "$1" ]] && return 0; done
  return 1
}

# open_umami_tunnel forwards localhost:3001 to Umami's dashboard on the host, in the background,
# as docs/deploy.md explains: Umami's container is on internal networks only.
open_umami_tunnel() {
  local umami
  # The container's address on its first network: the host routes to Docker's networks itself.
  umami=$(on_host <<<"docker inspect -f '{{range .NetworkSettings.Networks}}{{.IPAddress}} {{end}}' \$(docker compose ps -q umami)" | cut -d' ' -f1)
  [[ -n "$umami" ]] || { warn "Umami is not running on the host: deploy main first."; exit 1; }
  # -N: no remote command, only the tunnel; ExitOnForwardFailure: fail if the port is taken.
  ssh -N -o ExitOnForwardFailure=yes -L "3001:$umami:3000" "$DEPLOYER" &
  UMAMI_TUNNEL=$!
  sleep 2
  # kill -0 sends no signal: it only tests that the process still runs.
  kill -0 "$UMAMI_TUNNEL" 2>/dev/null || { warn "The tunnel did not open: is port 3001 free?"; exit 1; }
  say "✓ the tunnel is open: http://localhost:3001 is Umami's dashboard."
}

close_umami_tunnel() {
  if [[ -n "$UMAMI_TUNNEL" ]]; then kill "$UMAMI_TUNNEL" 2>/dev/null || true; fi
  UMAMI_TUNNEL=""
}

# check_in OUTCOME checks the import in from the importer's container, through the check-in the
# importer uses: `failed` pings the check's /fail, `succeeded` brings it back up. node reads its
# ES module from stdin, which `-T` hands it; the import resolves against the container's folder.
check_in() {
  on_host <<SH
docker compose exec -T -e OUTCOME=$1 importer node --input-type=module <<'JS'
const { importCheckInFromEnv } = await import('./dist/catalog-import/import-check-in-from-env.js');
await importCheckInFromEnv()(process.env.OUTCOME);
JS
SH
}

# report_api_error sends an error from the api's container, through the reporter its server uses,
# read from stdin as in check_in.
report_api_error() {
  on_host <<'SH'
docker compose exec -T api node --input-type=module <<'JS'
const { errorReporterFromEnv } = await import('./dist/error-reporting/error-reporter-from-env.js');
(await errorReporterFromEnv()).report(new Error('api test from the monitoring wizard'));
await new Promise((resolve) => setTimeout(resolve, 2000));
JS
SH
}

run_wizard() {

TOTAL_STAGES=11
cd "$(git rev-parse --show-toplevel)"
ENV_FILE=.env.vps
trap close_umami_tunnel EXIT
if ! { command -v gh >/dev/null && gh auth status >/dev/null 2>&1; }; then
  warn "gh is not signed in: run 'gh auth login' first."
  exit 1
fi
# The first address SECURITY.md gives: the only place it is written (spec #214).
MAILBOX=$(grep -oE '[[:alnum:]._%+-]+@[[:alnum:].-]+\.[[:alpha:]]+' SECURITY.md | head -n 1)
[[ -n "$MAILBOX" ]] || { warn "SECURITY.md gives no address."; exit 1; }

banner "Leyline monitoring in production"

stage "The VPS"
say "The tools' values go to the host's .env over SSH, as the deploy user."
ask VPS_ADDRESS "The VPS's IPv4 address:"
write_env VPS_ADDRESS "$VPS_ADDRESS"
ask DEPLOY_USER "The deploy user (empty: deploy):"
write_env DEPLOY_USER "${DEPLOY_USER:-deploy}"
ask DEPLOY_PATH "Where the stack lives on the VPS (empty: /srv/leyline):"
write_env DEPLOY_PATH "${DEPLOY_PATH:-/srv/leyline}"
ask APP_DOMAIN "The site's domain (empty: leyline.website):"
write_env APP_DOMAIN "${APP_DOMAIN:-leyline.website}"
DEPLOYER="$DEPLOY_USER@$VPS_ADDRESS"
on_host <<<'test -f .env' ||
  { warn "$DEPLOYER cannot log in, or $DEPLOY_PATH has no .env: run scripts/vps/setup-vps.sh first."; exit 1; }
say "✓ $DEPLOY_USER logs in, and $DEPLOY_PATH/.env is there."
say "Every tool alerts $MAILBOX, the project's mailbox that SECURITY.md gives:"
say "sign up to each with it, so the alerts reach it."
pause

stage "Bugsink: errors of the browser and the api"
if free_alerts_or_stop Bugsink "https://www.bugsink.com/#pricing"; then
  open_url "https://www.bugsink.com/register/15K/"
  step "Sign up for the free managed plan with $MAILBOX."
  step "Create a team if Bugsink asks for one, then 'New Project', named leyline → 'Save'."
  step "Turn on email alerts for the project, for new and regressed issues: a setting of your"
  note "  user, which a team or the project can override (Bugsink's alerts docs, opening now)."
  open_url "https://www.bugsink.com/docs/alerts/"
  step "Copy the project's DSN, https://<key>@<host>/<project>, from its setup page."
  if ask_host_env VITE_BUGSINK_DSN "Paste the DSN:" '^https://[[:alnum:]]+@[[:alnum:].-]+/[0-9]+$'; then
    # The DSN's scheme and host, and its project number, where Caddy forwards (docs/deploy.md).
    host_and_project=${VITE_BUGSINK_DSN#*@}
    write_host_env BUGSINK_ORIGIN "https://${host_and_project%%/*}"
    write_host_env BUGSINK_PROJECT_ID "${VITE_BUGSINK_DSN##*/}"
  fi
  pause
fi

stage "UptimeRobot: the site and /api/health"
if free_alerts_or_stop UptimeRobot "https://uptimerobot.com/pricing/"; then
  open_url "https://uptimerobot.com/"
  step "Sign up with $MAILBOX: the free plan emails the address you register with."
  step "'+ Add New Monitor' → HTTP(s) → URL https://$APP_DOMAIN/ → check $MAILBOX is"
  note "  among its alert contacts → 'Create monitor'."
  step "The same for https://$APP_DOMAIN/api/health, which checks the database too."
  note "  With the testers' guard on, both see the site down: that is expected (spec #214)."
  pause "Press Enter once both monitors are up."
fi

stage "Healthchecks.io: the daily import"
if free_alerts_or_stop Healthchecks.io "https://healthchecks.io/pricing/"; then
  open_url "https://healthchecks.io/"
  step "Sign up with $MAILBOX: the project's email integration then goes to it."
  step "Integrations: check there is an email integration to $MAILBOX, and confirm"
  note "  the address if Healthchecks.io sends it a link."
  step "Add a check named daily-import, with a Simple schedule as docs/deploy.md sets it:"
  sed -n '/^## Import monitoring/,/^## /p' docs/deploy.md | grep -E '^- \*\*(Period|Grace time)\*\*' |
    while IFS= read -r line; do note "  $line"; done
  step "Turn the email integration on for the check, then copy its ping URL."
  ask_host_env HEALTHCHECKS_PING_URL "Paste the ping URL (hidden):" \
    '^https://hc-ping\.com/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' hidden || true
  pause
fi

stage "Umami: the dashboard and the website"
say "Umami's dashboard opens only through an SSH tunnel to the host (docs/deploy.md)."
open_umami_tunnel
open_url "http://localhost:3001"
step "Sign in as admin, and if Umami still takes its default password (umami), change it now:"
note "  Settings → Security. Keep it in your password manager."
pause "Press Enter once the admin password is your own."
step "Settings → Websites → 'Add website': name leyline, domain $APP_DOMAIN → 'Save'."
step "Edit the website and copy its Website ID."
ask_host_env VITE_UMAMI_WEBSITE_ID "Paste the Website ID:" \
  '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' || true
close_umami_tunnel

stage "Deploy"
say "The DSN and the website id reach the browser only through a new build of the web image,"
say "and the privacy notice describes each tool from that build on (ADR 0027)."
if ! confirm "Deploy main now?"; then
  say "Deploy later with scripts/vps/deploy-main.sh, then run this wizard again for the checks."
  exit 0
fi
scripts/vps/deploy-main.sh
# The latest release is the version the site now serves: a deploy of a version already released
# keeps its tag (docs/deploy.md). Tags are `vX.Y.Z`; the errors carry `X.Y.Z` (ADR 0025).
RELEASE=$(gh release view --json tagName --jq .tagName)
RELEASE=${RELEASE#v}
say "✓ deployed: the site serves $RELEASE."
pause

stage "Check the stack"
say "pnpm check:staging checks that the error and event paths forward, that Umami's dashboard"
say "is not on the site, and that nothing of the client's reaches the tools."
pnpm exec playwright install chromium
# The site is open, so the check needs no credential. ${DEPLOY_PATH##*/} is its last folder,
# which Compose names the stack after (docs/deploy.md).
DOCKER_HOST="ssh://$DEPLOYER" COMPOSE_PROJECT_NAME="${DEPLOY_PATH##*/}" \
  pnpm check:staging --access open --app "https://$APP_DOMAIN"
CHECKED+=("\`pnpm check:staging --access open\` passa su https://$APP_DOMAIN")
pause

stage "Check: errors reach Bugsink"
if is_off Bugsink; then
  note "Bugsink is off: nothing to check."
else
  open_url "https://$APP_DOMAIN/"
  step "Open the browser's console on the site and run:"
  note "  setTimeout(() => { throw new Error('browser test from the monitoring wizard') })"
  say "Sending an error from the api, through the reporter its server uses:"
  report_api_error
  step "In Bugsink, check both errors are there under release $RELEASE, with no IP address."
  if confirm "Are they?"; then
    CHECKED+=("un errore di prova del browser e uno dell'API arrivano a Bugsink con la release $RELEASE, senza indirizzo IP")
  else
    SKIPPED+=("Bugsink: the test errors did not arrive as expected")
  fi
fi

stage "Check: alerts reach the mailbox"
if ! is_off UptimeRobot; then
  open_url "https://uptimerobot.com/"
  step "Sign in, open the monitor of https://$APP_DOMAIN/ → 'Test Notification' → email."
  if confirm "Did $MAILBOX receive the test alert?"; then
    CHECKED+=("l'avviso di prova di UptimeRobot arriva alla casella di \`SECURITY.md\`")
  else
    SKIPPED+=("UptimeRobot: no test alert reached the mailbox")
  fi
fi
if ! is_off Healthchecks.io; then
  say "Checking a failure in from the importer, through the check-in it uses:"
  check_in failed
  if confirm "Did $MAILBOX receive Healthchecks.io's alert?"; then
    CHECKED+=("l'avviso di prova di Healthchecks.io arriva alla casella di \`SECURITY.md\`")
  else
    SKIPPED+=("Healthchecks.io: no alert reached the mailbox")
  fi
  check_in succeeded
  say "✓ checked a success in: the check is up again."
fi
pause

stage "Check: Umami's events"
open_umami_tunnel
open_url "https://$APP_DOMAIN/"
step "Paste a decklist on the site and make its PDF."
open_url "http://localhost:3001"
step "In Umami's dashboard, open the website's events."
if confirm "Does it show a decklist_resolved and a pdf_generated, with counts and no card names?"; then
  CHECKED+=("la dashboard di Umami si apre dal tunnel SSH e mostra \`decklist_resolved\` e \`pdf_generated\`, senza nomi di carte")
else
  SKIPPED+=("Umami: the events did not show as expected")
fi
close_umami_tunnel

stage "Record the checks on #214"
comment="Monitoraggio acceso in produzione il $(date +%F), release $RELEASE. Verifiche passate:"$'\n'
for check in "${CHECKED[@]}"; do comment+=$'\n'"- [x] $check"; done
if (( ${#TURNED_OFF[@]} )); then
  comment+=$'\n\n'"Restano spenti, perché il piano gratuito non manda avvisi via email: ${TURNED_OFF[*]}."
fi
say "The comment:"
printf '%s\n' "$comment" | while IFS= read -r line; do note "  $line"; done
if confirm "Post it on #214?"; then
  gh issue comment 214 --body "$comment"
else
  SKIPPED+=("the comment on #214")
fi

finish
if (( ${#WRITTEN_HOST[@]} )); then
  note "wrote ${#WRITTEN_HOST[@]} value(s) to the host's .env: ${WRITTEN_HOST[*]}"
  printf '\n'
fi
}

run_wizard "$@"; exit
